import * as React from "react";

import { cn } from "../lib/utils";
import { normalizeCodeLanguage, tokenizeCode } from "./code-tokenizer";

import styles from "./code.module.css";

export type CodeProps = Omit<React.ComponentPropsWithoutRef<"code">, "children"> & {
  code?: string;
  language?: string;
  format?: "syntax" | "plain";
  lineNumbers?: boolean;
  highlight?: readonly number[];
  wrap?: boolean;
  maxLines?: number;
  maxHeight?: React.CSSProperties["maxHeight"];
  label?: string;
} & ({ block?: false; children?: React.ReactNode } | { block: true; children?: string });
export function Code({
  children,
  code,
  block = false,
  language = "text",
  format = "syntax",
  lineNumbers = false,
  highlight = [],
  wrap = false,
  maxLines,
  maxHeight,
  label,
  className,
  style,
  ref,
  ...props
}: CodeProps & { ref?: React.Ref<HTMLElement> }) {
  if (!block)
    return (
      <code
        ref={ref}
        data-slot="code"
        className={cn(styles.code, styles.inline, className)}
        style={style}
        {...props}
      >
        {code ?? children}
      </code>
    );
  const value = code ?? (typeof children === "string" ? children : "");
  return (
    <pre
      data-slot="code-block-content"
      tabIndex={0}
      role="region"
      aria-label={label ?? `${language} code`}
      data-scroll-fade="both"
      className={cn(styles.code, styles.block, wrap && styles.wrap, className)}
      style={{
        maxHeight:
          maxHeight ??
          (maxLines ? `calc(${maxLines} * 1lh + 2 * var(--cipher-space-surface-inset))` : undefined),
        ...style
      }}
    >
      <code ref={ref} data-language={normalizeCodeLanguage(language)} {...props}>
        {value.split("\n").map((line, index, lines) => (
          <React.Fragment key={index}>
            <span className={cn(styles.line, highlight.includes(index + 1) && styles.highlight)}>
              {lineNumbers && (
                <span aria-hidden="true" className={styles.number}>
                  {index + 1}
                </span>
              )}
              {tokenizeCode(line, format === "plain" ? "plain" : language).map(
                (token, tokenIndex) => (
                  <span key={tokenIndex} className={styles[`token_${token.kind}`]}>
                    {token.text}
                  </span>
                )
              )}
            </span>
            {index < lines.length - 1 ? "\n" : null}
          </React.Fragment>
        ))}
      </code>
    </pre>
  );
}
Code.displayName = "Code";

export type CodeToken = {
  text: string;
  kind: "plain" | "comment" | "string" | "keyword" | "number" | "key";
};
const aliases: Record<string, string> = {
  text: "plain",
  txt: "plain",
  plaintext: "plain",
  sh: "shell",
  bash: "shell",
  zsh: "shell",
  shell: "shell",
  dotenv: "env",
  env: "env",
  json: "json",
  yml: "yaml",
  yaml: "yaml",
  js: "javascript",
  jsx: "javascript",
  javascript: "javascript",
  ts: "typescript",
  tsx: "typescript",
  typescript: "typescript",
  py: "python",
  python: "python",
  tf: "hcl",
  terraform: "hcl",
  hcl: "hcl"
};
export function normalizeCodeLanguage(language: string): string {
  return aliases[language.toLowerCase()] ?? "plain";
}
export function tokenizeCode(text: string, language: string): CodeToken[] {
  const normalized = normalizeCodeLanguage(language);
  if (normalized === "plain") return [{ text, kind: "plain" }];
  const expression =
    /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\/\*[\s\S]*?\*\/|\/\/[^\n]*|#[^\n]*|\b(?:true|false|null|undefined|None|True|False|const|let|var|function|return|import|from|export|default|async|await|if|else|for|while|class|def|try|except|raise|with|as|in|not|and|or|resource|variable|output|provider|module|locals|data|terraform)\b|-?\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b|\b[A-Za-z_][\w-]*(?=\s*[:=]))/g;
  const result: CodeToken[] = [];
  let end = 0;
  Array.from(text.matchAll(expression)).forEach((match) => {
    const index = match.index ?? 0;
    if (index > end) result.push({ text: text.slice(end, index), kind: "plain" });
    const part = match[0];
    const comment = part.startsWith("#")
      ? ["shell", "env", "yaml", "python", "hcl"].includes(normalized)
      : part.startsWith("//") || part.startsWith("/*")
        ? ["javascript", "typescript", "hcl"].includes(normalized)
        : false;
    const kind = comment
      ? "comment"
      : /^["'`]/.test(part)
        ? "string"
        : /^-?\d/.test(part)
          ? "number"
          : /^[A-Za-z_][\w-]*$/.test(part) &&
              /[:=]/.test(text.slice(index + part.length).trimStart()[0] ?? "")
            ? "key"
            : "keyword";
    result.push({
      text: part,
      kind:
        (part.startsWith("#") || part.startsWith("//") || part.startsWith("/*")) && !comment
          ? "plain"
          : kind
    });
    end = index + part.length;
  });
  if (end < text.length) result.push({ text: text.slice(end), kind: "plain" });
  return result;
}

.code {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  color: var(--cipher-text2, var(--foreground));
}
.inline {
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft, var(--border));
  border-radius: 0;
  padding: var(--cipher-space-2) var(--cipher-space-4);
  background: var(--cipher-tint, var(--muted));
  overflow-wrap: anywhere;
}
.block {
  margin: 0;
  overflow: auto;
  padding: var(--cipher-space-surface-inset);
  tab-size: 2;
  white-space: pre;
  outline-offset: -2px;
}
.wrap {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.line {
  display: inline-block;
  min-height: var(--cipher-type-mono-line-height);
  min-width: 100%;
}
.highlight {
  background: var(--cipher-accent-wash, var(--muted));
  min-width: calc(100% + 2 * var(--cipher-space-surface-inset));
  margin-inline: calc(-1 * var(--cipher-space-surface-inset));
  padding-inline: var(--cipher-space-surface-inset);
}
.number {
  display: inline-block;
  width: 3ch;
  margin-right: var(--cipher-space-content-group);
  text-align: right;
  color: var(--cipher-muted, var(--muted-foreground));
  user-select: none;
}
.codeBlock {
  width: 100%;
}
.codeBlock > .header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-space-40);
  padding: var(--cipher-space-4) var(--cipher-space-3) var(--cipher-space-4)
    calc(var(--cipher-space-12) - var(--cipher-size-control-border));
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
  color: var(--cipher-text2);
}
.codeBlock > .header :global([data-slot="icon"]) {
  width: var(--cipher-size-icon-sm);
  height: var(--cipher-size-icon-sm);
  flex: none;
  color: var(--cipher-muted);
}
.body {
  overflow: hidden;
}
.identity {
  grid-column: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--cipher-space-control-gap);
}
.actions {
  grid-column: 2;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: end;
  gap: var(--cipher-space-control-slot-gap);
}
.header > :global([data-slot="copy-button"]) {
  display: contents;
}
.header > :global([data-slot="copy-button"]) > :global(button) {
  grid-column: -2 / -1;
}
.header > :global([data-slot="copy-button"]) > :global([data-copy-feedback]):not(:empty) {
  grid-column: 1 / -1;
}
.customContent {
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
  padding: var(--cipher-space-surface-inset);
}
.tree {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
  overflow: auto;
  padding: var(--cipher-space-surface-inset);
}
.entry {
  display: flex;
  align-items: baseline;
  white-space: pre;
}
.treeCaret {
  display: inline-block;
  flex: none;
  width: var(--cipher-space-16);
}
.key {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 600;
}
.primitive {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 500;
}
.string {
  color: var(--cipher-text2, var(--foreground));
}
.punctuation {
  color: var(--cipher-muted, var(--muted-foreground));
}
.snippet {
  --cipher-nested-action-height: var(--cipher-size-nested-md);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--cipher-space-control-slot-gap);
  min-width: 0;
  border: var(--cipher-size-control-border) solid var(--cipher-control, var(--border));
  border-radius: 0;
  background: var(--cipher-surface, var(--background));
  padding: var(--cipher-space-control-slot-inset);
  padding-inline-start: var(--cipher-space-control-inline);
  min-height: var(--cipher-size-control-md);
}
.snippetSmall {
  --cipher-nested-action-height: var(--cipher-size-nested-sm);
  min-height: var(--cipher-size-control-sm);
}
.prompt {
  color: var(--cipher-muted, var(--muted-foreground));
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  user-select: none;
}
.input {
  flex: 1;
  width: 0;
  min-width: min(100%, 10ch);
  flex-basis: 10ch;
  border: 0;
  outline: none;
  background: transparent;
  color: inherit;
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}
.snippet[data-multiline] {
  align-items: flex-start;
}
.snippet[data-multiline] > .prompt {
  padding-block: calc((var(--cipher-nested-action-height) - 1lh) / 2);
}
/* field-sizing: content ignores rows and is missing in older targets, so the line count also sets a minimum height; content past it scrolls. */
.snippetLines {
  box-sizing: content-box;
  min-height: calc(var(--cipher-snippet-rows) * 1lh);
  max-height: calc(var(--cipher-snippet-lines) * 1lh);
  padding-block: calc((var(--cipher-nested-action-height) - 1lh) / 2);
  overflow-y: auto;
  resize: none;
  field-sizing: content;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.snippet {
  transition-property: border-color, box-shadow;
  transition-duration: var(--cipher-duration-fast);
  transition-timing-function: var(--cipher-ease-fade);
}
.snippet[data-input-focus] {
  border-color: var(--cipher-ink);
  box-shadow: 0 0 0 var(--cipher-size-focus-glow) var(--cipher-focus-ring);
}
.snippet > :global([data-slot="copy-button"]) {
  display: contents;
}
.snippet > :global([data-slot="copy-button"]) > :global([data-copy-feedback]):not(:empty) {
  flex-basis: 100%;
}
.token_comment {
  color: var(--cipher-muted, var(--muted-foreground));
  font-style: italic;
}
.token_string {
  color: var(--cipher-text2, var(--foreground));
}
.token_keyword,
.token_number {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 500;
}
.token_key {
  color: var(--cipher-ink, var(--foreground));
  font-weight: 600;
}
.blockLabel {
  flex: 1;
  width: auto;
}
.treeNode {
  min-width: 0;
}
.treeToggle {
  display: inline-flex;
  align-items: center;
  min-width: var(--cipher-size-nested-sm);
  min-height: var(--cipher-size-nested-sm);
  text-align: start;
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
}
.treeToggle:focus-visible {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: var(--cipher-size-focus-ring);
}
.treeChildren {
  margin-left: calc(var(--cipher-space-6) - var(--cipher-size-control-border));
  padding-left: var(--cipher-space-10);
  border-left: var(--cipher-size-control-border) solid var(--cipher-line);
}
.notice {
  margin: var(--cipher-space-8) 0;
  color: var(--cipher-muted, var(--muted-foreground));
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.wrap .entry {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
@media (max-width: 480px) {
  .header[data-has-actions] .identity {
    grid-column: 1 / -1;
  }
  .header .actions {
    grid-column: 1 / 3;
    justify-content: start;
  }
}

.header[data-has-actions] {
  grid-template-columns: minmax(0, 1fr) auto auto;
}
